llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Aprepitant, a closely transferable CNS-active piperidine/heteroaryl drug, has absolute oral bioavailability of 65% (95% CI 57–75%) in fasted men, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Silodosin has an absolute oral bioavailability of 32.2% in healthy adult men under fasted conditions, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Bepotastine exhibits high oral bioavailability in humans, with absorption reported as >80%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Lemborexant is at least 87% bioavailable after oral administration based on human radiolabel mass-balance data, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride has an absolute oral availability of 72.5% compared with intravenous administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Basmisanil has an absolute oral bioavailability of approximately 75% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Setipiprant has human oral bioavailability of at least 50%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Haloperidol, a structurally related CNS piperidine drug, has absolute oral bioavailability of 60–70%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "LY2196044 has an estimated absolute oral bioavailability of 45% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Encainide has an oral bioavailability of 30 ± 7% in normal subjects; despite interindividual variability, quantitative values remain at or above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values ≥20%, mostly 32–87%, and the query shares CNS-drug-like features with these compounds; therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule itself.",
    "Encainide shows wide interindividual variability, with some qualitative reports of low bioavailability, but quantitative values in normal subjects are 20–42% and do not affirmatively establish F < 20%.",
    "Most evidence comes from other drugs rather than the query, although the assay-transfer scores are very high."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

